'use strict';
const gms={pumpOn:false,pumping:false,pressure:760,on:false,source:25,quad:25,transfer:25,from:null,autoEnable:false,pumpFrame:0,lastPaint:0,liveId:null,message:'Select MS as the detector, load a sample and prepare the instrument.'};
function gcMSReady(){return gms.pumpOn&&!gms.pumping&&gms.pressure<=5e-5&&gms.on&&gc.ready&&gc.power&&gc.carrier&&Math.abs(gms.source-gc.method.msSource)<.1&&Math.abs(gms.quad-gc.method.msQuad)<.1&&Math.abs(gms.transfer-gc.method.msTransfer)<.1}
function gcMSTemp(zone){const to={source:'msSource',quad:'msQuad',transfer:'msTransfer'}[zone];return gc.warming?(gms.from?.[zone]??gms[zone])+(gc.method[to]-(gms.from?.[zone]??gms[zone]))*gc.warm:gms[zone]}
function gcMSRefresh(){if(typeof page==='undefined')return;if(page==='massspec')msRender();else if(page==='instrumentation')gcRender()}
function gcMSSetDetector(value){if(gcLocked()||gseq.active)return;gc.method.detectorType=value==='ms'?'ms':'fid';gc.ready=false;gc.flame=false;gms.on=false;gms.autoEnable=false;gms.message=gcIsMS()?'MS selected. Prepare vacuum and temperatures before injection.':'FID selected. Equilibrate, then ignite the FID.';gcSave();gcMSRefresh()}
function gcMSReset(){cancelAnimationFrame(gms.pumpFrame);Object.assign(gms,{pumpOn:false,pumping:false,pressure:760,on:false,source:25,quad:25,transfer:25,autoEnable:false});}
function gcMSWarmStart(){if(!gcIsMS())return;gms.from={source:gms.source,quad:gms.quad,transfer:gms.transfer};gms.on=false;}
function gcMSWarmFinish(){if(!gcIsMS())return;gms.source=gc.method.msSource;gms.quad=gc.method.msQuad;gms.transfer=gc.method.msTransfer;if(gms.autoEnable&&gms.pumpOn&&!gms.pumping&&gms.pressure<=5e-5)gms.on=true;gms.message=gms.on?'GC–MS ready. Inject the loaded sample.':'MS temperatures are stable. Prepare MS to establish vacuum and enable acquisition.';}
function gcMSPrepare(){if(!gcIsMS()||gcLocked()||gseq.active)return false;if(!gc.power||!gc.carrier){gms.message='Power on and enable carrier gas first.';gcMSRefresh();return false}const errors=gcValidation(gc.method);if(errors.length){gms.message=errors.join(' ');gcMSRefresh();return false}gms.autoEnable=true;gms.on=false;gcEquilibrate();if(gms.pumpOn&&gms.pressure<=5e-5){gms.pressure=6.26e-6*gc.method.flow;gms.message='Vacuum retained; equilibrating the GC and MS heated zones.';gcMSRefresh();return true}gms.pumpOn=true;gms.pumping=true;const start=performance.now(),from=Math.max(gms.pressure,6.26e-6*gc.method.flow),target=6.26e-6*gc.method.flow;gms.message='Accelerated pump-down and temperature stabilization in progress.';function pump(now){const f=Math.min(1,(now-start)/4500);gms.pressure=Math.exp(Math.log(from)+(Math.log(target)-Math.log(from))*f);if(f<1){gcMSPaint(now);gms.pumpFrame=requestAnimationFrame(pump)}else{gms.pumping=false;gms.pressure=target;if(gc.ready&&gms.autoEnable)gms.on=true;gms.message=gcMSReady()?'GC–MS ready. Inject the loaded sample.':'Vacuum established. Waiting for temperatures.';gcMSRefresh()}}gms.pumpFrame=requestAnimationFrame(pump);gcMSRefresh();return true}
function gcMSStatus(){return !gc.power?'POWER OFF':gms.pumping?'PUMPING DOWN':gc.warming?'EQUILIBRATING':gc.running&&gc.run?.method.detectorType==='ms'?'ACQUIRING':gc.paused&&gc.run?.method.detectorType==='ms'?'PAUSED':gc.run?.method.detectorType==='ms'&&gc.run.completed&&!gc.preparingNext?'RUN COMPLETE':gc.run?.method.detectorType==='ms'&&gc.run.stopped&&!gc.preparingNext?'STOPPED':gcMSReady()?'READY':!gms.pumpOn?'VENTED':gms.on?'IDLE':'MS STANDBY'}
function gcMSLiveData(){return ms.datasets.find(d=>d.id===gms.liveId)||null}
function gcMSSnapshot(){return {pressureTorr:gms.pressure,sourceC:gcMSTemp('source'),quadC:gcMSTemp('quad'),transferC:gcMSTemp('transfer'),injectorC:gc.actualInjector,ovenC:gcActualOven(),pumpOn:gms.pumpOn,detectorOn:gms.on}}
function gcMSBeginRun(){const r=gc.run;if(!r||r.method.detectorType!=='ms')return;const label=r.calibration?gcVialLabel(r.calibration):'GC–MS run '+(ms.counter+1),d={kind:'SIMLAB_MS_COMPANION',schema:1,acquisition:'direct',id:'ms-'+Date.now().toString(36)+'-'+(++ms.counter),title:label,created:new Date().toISOString(),source:'Direct simulated GC–MS acquisition',acquired:0,complete:false,live:true,dt:MS_DT,method:{...r.method},instrument:gcMSSnapshot(),components:r.components.map(c=>({id:c.id,name:c.name,mass:c.mass,tr:c.tr,sigma:c.sigma})),fid:[],sourcePeaks:[],assignments:[],notes:''};r.msDatasetId=d.id;gms.liveId=d.id;ms.datasets.push(d);ms.datasets=ms.datasets.slice(-4);ms.active=d.id;ms.scan=0;ms.peak=null;ms.subtract=false;msInvalidate();ms.message='Acquiring directly with the MS detector. TIC and spectra show only scans acquired so far; analysis unlocks when acquisition ends.';gms.message='MS detector acquiring directly. Monitor the TIC, vacuum and temperatures.';gms.lastPaint=0;go('massspec')}
function gcMSUpdateRun(final=false){const r=gc.run,d=gcMSLiveData();if(!r||r.method.detectorType!=='ms'||!d||r.msDatasetId!==d.id)return;d.acquired=gc.time;d.complete=!!r.completed;d.live=!final;d.instrument=gcMSSnapshot();msCache.delete(d.id);if(final){gms.message=r.completed?'MS run complete. Vacuum is retained; load another sample and prepare the next injection.':'MS acquisition stopped. Acquired scans have been retained.';ms.subtract=true;msSelectDataset(d.id);ms.message=r.completed?'Direct GC–MS run complete. Select a TIC peak to inspect its spectrum and search the library.':'MS acquisition stopped. Only acquired scans are retained.';msSave();}else{ms.scan=Math.floor(d.acquired/d.dt);ms.peak=null;msInvalidate()}if(typeof page!=='undefined'&&page==='massspec')msRender()}
function gcMSPaint(now=performance.now(),force=false){if(now-gms.lastPaint<600&&!force)return;gms.lastPaint=now;if(gc.running||gc.paused){gcMSUpdateRun();return}if(typeof page!=='undefined'&&page==='massspec')msRender();else if(page==='instrumentation'){const el=document.getElementById('gcMSPanel');if(el)el.outerHTML=gcMSPanel(false)}}
function gcMSDataSignal(){const d=gcMSLiveData();if(!d||!d.acquired)return '0.00 a.u.';const t=msTrace(d);return gcFmt(t.tic.at(-1)||0,2)+' a.u.'}
function gcMSPeakCount(){const d=gcMSLiveData();return d?msTrace(d).peaks.length:0}
function gcMSPanel(full=true){const mode=gcIsMS(),locked=gcLocked()||gseq.active,live=!!gcMSLiveData()?.live;return `<section class="panel gc-panel gc-ms-panel" id="gcMSPanel"><div class="ms-title"><div><span class="eyebrow">MS INSTRUMENT STATUS · SIMULATED</span><h2>Vacuum &amp; temperatures</h2></div><span class="pill">${gcMSStatus()}</span></div><div class="gc-ms-readouts"><div class="gc-stat"><small>High vacuum / Torr</small><b>${gms.pressure.toExponential(2)}</b><small>${(gms.pressure*133.322).toExponential(2)} Pa · ${gms.pumping?'Pumping':gms.pumpOn?'Pump on':'Vented'}</small></div><div class="gc-stat"><small>Ion source · actual / setpoint</small><b>${gcFmt(gcMSTemp('source'),0)} / ${gc.method.msSource} °C</b></div><div class="gc-stat"><small>Quadrupole · actual / setpoint</small><b>${gcFmt(gcMSTemp('quad'),0)} / ${gc.method.msQuad} °C</b></div><div class="gc-stat"><small>Transfer line · actual / setpoint</small><b>${gcFmt(gcMSTemp('transfer'),0)} / ${gc.method.msTransfer} °C</b></div><div class="gc-stat"><small>GC oven · actual / initial</small><b>${gcFmt(gcActualOven(),1)} / ${gc.method.initial} °C</b></div><div class="gc-stat"><small>Detector / acquired time</small><b>${gms.on?'MS on':'Standby'} · ${gcFmt(gc.time,2)} min</b></div></div>${full?`<div class="ms-controls"><label class="gc-field">Acquisition detector<select data-gcms-detector ${locked?'disabled':''}><option value="fid" ${!mode?'selected':''}>FID</option><option value="ms" ${mode?'selected':''}>MS · electron ionization</option></select></label><label class="gc-field">Load MS sample<select id="gcMSVial" ${locked?'disabled':''}><option value="">Choose a bench vial</option>${gcal.vials.filter(v=>v.exported).map(v=>`<option value="${v.id}" ${gcal.loaded===v.id?'selected':''}>${gcPrepEsc(gcVialLabel(v))} · ${v.role}</option>`).join('')}</select></label><button class="btn secondary small" data-gcms-action="load" ${locked||!mode?'disabled':''}>Load sample</button></div><div class="gc-actions"><button class="btn secondary small" data-gcms-action="power" ${locked?'disabled':''}>${gc.power?'Power off':'Power on'}</button><button class="btn secondary small" data-gcms-action="carrier" ${locked||!gc.power?'disabled':''}>${gc.carrier?'Carrier gas: ON':'Turn carrier gas on'}</button><button class="btn" data-gcms-action="prepare" ${locked||!mode?'disabled':''}>Prepare MS</button><button class="btn" data-gcms-action="inject" ${locked||!mode||!gcMSReady()?'disabled':''}>Inject &amp; run MS</button><button class="btn secondary small" data-gcms-action="pause" ${!gc.running&&!gc.paused?'disabled':''}>${gc.paused?'Resume':'Pause'}</button><button class="btn secondary small" data-gcms-action="stop" ${!gc.running&&!gc.paused?'disabled':''}>Stop acquisition</button><button class="btn secondary small" data-go="instrumentation">Method &amp; column setup</button></div>`:`<div class="gc-actions"><button class="btn small" data-gcms-action="prepare" ${locked?'disabled':''}>Prepare MS</button><button class="btn secondary small" data-go="massspec">Open MS instrument &amp; data</button></div>`}<p class="gc-notice" role="status">${gcPrepEsc(gms.message)}</p>${live?'<p><b>Acquisition is live.</b> Analysis controls unlock after completion or Stop acquisition. The TIC and spectrum contain acquired scans only.</p>':''}<details class="gc-detail"><summary>Status model and operating references</summary><p>All readouts are simulated. Pump-down and heating are accelerated to seconds for training. This configuration uses helium, a simplified turbo-pump pressure model proportional to column flow, and an illustrative readiness threshold of 5 × 10⁻⁵ Torr. It is not a procedure or specification for real hardware.</p><p>Example source (230 °C) and quadrupole (150 °C) settings and vacuum/status displays are documented in the <a href="https://www.agilent.com/cs/library/usermanuals/public/G7077-90014.pdf" target="_blank" rel="noopener">Agilent 5977 MSD operation manual</a>. Temperatures and pressure gate acquisition here; their effects on fragmentation and sensitivity are not quantitatively simulated. EI patterns remain the attributed NIST reference patterns. Tune, leaks and pressure faults are not fully modelled.</p></details></section>`}
function gcMSInstrument(){const r=gc.run,m=r&&(gc.running||gc.paused)?r.method:gc.method,idx=gcIndex();return `<svg viewBox="0 0 800 260" role="img" aria-label="GC-MS schematic with vacuum and heated transfer line"><rect x="25" y="30" width="140" height="190" rx="12" fill="#fff" stroke="#b3cbbc"/><rect x="190" y="20" width="350" height="210" rx="12" fill="#e1ede4" stroke="#b3cbbc"/><rect x="565" y="30" width="210" height="190" rx="12" fill="#fff" stroke="#b3cbbc"/><text x="95" y="60" text-anchor="middle">INJECTOR</text><text x="365" y="52" text-anchor="middle">COLUMN OVEN</text><path d="M95 90V125H220V80H505V110H220V145H505V175H220V125H600" fill="none" stroke="#7b9b88" stroke-width="5"/>${(r?r.components:gcSamples()).map(c=>{const pos=r?c.positions[idx]:0;return pos>0&&pos<1?`<circle cx="${220+285*pos}" cy="${125+35*Math.sin(pos*18)}" r="5" fill="${c.color}"/>`:''}).join('')}<text x="95" y="185" text-anchor="middle">${gcFmt(gc.actualInjector,0)} °C</text><text x="365" y="210" text-anchor="middle">${gcFmt(gcActualOven(),1)} °C</text><text x="670" y="60" text-anchor="middle">EI → QUADRUPOLE → MS</text><path d="M600 125H735" stroke="#087e67" stroke-width="3"/><circle cx="615" cy="125" r="12" fill="${gms.on?'#c4ef91':'#e2eae5'}"/><text x="670" y="95" text-anchor="middle">Transfer ${gcFmt(gcMSTemp('transfer'),0)} °C</text><text x="670" y="165" text-anchor="middle">${gms.pressure.toExponential(2)} Torr</text><text x="670" y="192" text-anchor="middle">${gms.on?'MS acquisition enabled':'MS standby'}</text></svg>`}
document.addEventListener('change',e=>{if(e.target.hasAttribute('data-gcms-detector'))gcMSSetDetector(e.target.value)});
document.addEventListener('click',e=>{const action=e.target.closest('[data-gcms-action]')?.dataset.gcmsAction;if(!action)return;if(action==='pause'){gcPause();gms.message=gc.paused?'MS acquisition paused. Resume or stop the run.':'MS acquisition resumed.';gcMSUpdateRun();gcMSRefresh();return}if(action==='stop'){gcStop();gcMSRefresh();return}if(gcLocked()||gseq.active)return;if(action==='load'){const id=Number(document.getElementById('gcMSVial')?.value);if(!gcal.vials.some(v=>v.id===id&&v.exported)){gms.message='Choose an exported bench vial.';}else{gcCalLoad(id);gms.message='Sample loaded. Prepare MS if needed, then inject.';}}if(action==='power'){gc.power=!gc.power;gc.ready=false;gc.flame=false;if(!gc.power){gc.carrier=false;gc.actualInjector=25;gc.actualOven=25;gcMSReset();}}if(action==='carrier'&&gc.power){gc.carrier=!gc.carrier;gc.ready=false;gms.on=false;}if(action==='prepare'){gcMSPrepare();return}if(action==='inject'){gcStart();return}gcMSRefresh()});
